                "context": "Cet exercice comprend 10 questions. Pour chaque QCM, vous indiquerez la ou les proposition(s) exacte(s).\nLes tumeurs sont des pathologies caractérisées par une prolifération anormale et incontrôlée des cellules. Lorsque ces cellules acquièrent la capacité d’envahir les tissus environnants et de se disséminer à distance, on parle de tumeur maligne ou cancer. Le développement tumoral résulte de l’accumulation d’altérations génétiques et moléculaires qui perturbent les mécanismes contrôlant la prolifération, la survie et la différenciation cellulaire.\nParmi les voies de signalisation impliquées dans ces processus, la voie des MAP kinases (Mitogen-Activated Protein Kinases, MAPK) occupe une place centrale.\nLes chercheurs s’intéressent ainsi aux conséquences de la dérégulation de cette voie de signali-sation sur la prolifération tumorale.",
