                "question": "L’ouabaïne est un inhibiteur de la pompe \\(Na^{+}/\\)\\(K^{+}.\\) On cherche alors les effets de cette molécule sur l’homéostasie cellulaire. En tenant compte de cette information et de vos connaissances, on pourrait obser- ver :",
