                        "isCorrect": false,
                        "explanation": "FAUX - Petit piège attention ! En observant la structure cellulaire, les cellules sécrétant des protéines (comme la cellule principale gastrique) et les cellules sécrétant du mucigène (comme la cellule caliciforme intestinale) partagent une organisation basale identique : elles possèdent toutes les deux un réticulum endoplasmique granuleux (REG) très développé et situé en position basale ! La vraie différence réside dans la région apicale et la nature des granules de sécrétion : les cellules à mucigène présentent de très larges vésicules de mucine claires au pôle apical qui refoulent le reste des organites, tandis que les cellules à protéines ont des granules de sécrétion plus denses et un appareil de Golgi supranucléaire très visible."
