                        "text": "La démarche utilisée par John Snow pour trouver le mode de transmission du choléra illustre la démarche épidémiologique",
                        "isCorrect": true,
                        "explanation": "VRAI - Ouii toutafé !! John Snow a pu cibler le problème. En effet, le choléra se transmettait par l’eau et non les miasmes comme ce qui a pu être pensé à l’époque."
