                        "isCorrect": false,
                        "explanation": "FAUX - Qui dit dernier item, dit dernier piège . Tout est vrai sauf que c’est 1300 médecins généralistes et non 1400. Ces pièges sont là pour que vous fassiez attention à tous les détails, courage ça va le faire. Vous êtes des goats !!!"
