                "num": 7,
                "type": "QCM",
                "context": "La multimorbidité est définie par la présence d’au moins une pathologie chronique\nLes mesures négatives de la santé sont plus opérationnelles que les mesures positives\nLes indicateurs de qualité de vie sont des indicateurs multidimensionnels et subjectifs\nLes indicateurs fonctionnels abordent la santé en termes de conséquences des maladies\nLe choix d’un indicateur de santé, plutôt qu’un autre est un choix politique qui doit être fait à la lumière de priorités de santé prédéfinies\nConcernant les grands problèmes de santé en France, laquelle (lesquelles) des pro-positions suivantes est (sont) exacte(s) ?\nLa santé de la population desservie est un état de santé moyen prenant en compte les différences entre les personnes ayant un très bon état de santé et les personnes ayant un mauvais état de santé\nLa conception positive de la santé désigne le fait que les professionnels de santé doivent adopter un comportement optimiste face aux patients\nLa possession du meilleur état de santé qu’il est capable d’atteindre constitue l’un des droits fondamentaux de tout être humain\nL’objectif de la bonne santé, dans le cadre de l’amélioration de la santé de la population desservie, est double : la qualité (la plus faible différence possible entre individus et entre groupes) et l’équité (le meilleur niveau moyen réalisable)\nRéduire les décès évitables, les incapacités évitables et les inégalités face à la santé font partie des objectifs d’une politique de santé\nD’après vos connaissances et par lecture du graphique, parmi les propositions sui-vantes, laquelle (lesquelles) est (sont) exacte(s) ?\nEn 2006, parmi les hommes ayant une HTA, 54,6% des hommes ont une HTA non traitée\nQue ce soit en 2006 ou en 2015, chez les hommes comme chez les femmes, la majorité des patients ayant une HTA ne sont pas traités\nLe pourcentage des femmes ayant une HTA traitée contrôlée en 2015 a diminué comparé à celui de 2006\nLe pourcentage des hommes ayant une HTA traitée contrôlée est le même en 2006 et 2015, soit 19%\nL’HTA est un facteur de risque des maladies cardio-vasculaires\nConcernant les grands problèmes de santé en France, laquelle (lesquelles) des pro-positions suivantes est (sont) exacte(s) ?\nUn des grands objectifs d’une politique de santé est de répondre aux attentes des gens\nLe rapport de la DREES datant de 2022 souligne l’importance des troubles anxieux et dépressifs dans la population\nLa démarche de santé publique est faite de 5 étapes et se termine par la mise en place d’actions de santé\nLa période hygiéniste précède la période biomédicale et permet la baisse de la mortalité infectieuse grâce à l’amélioration de la qualité de l’environnement\nL’évolution de l’incidence du cancer entre 1990 et 2023 est principalement liée à une aug-mentation de risque de cancer",
